<?php
declare(strict_types=1);
require_once __DIR__.'/includes/env.php'; require_once __DIR__.'/database/db.php'; require_once __DIR__.'/includes/public_helpers.php';
$search=trim((string)($_GET['search']??''));$category=trim((string)($_GET['category']??''));$page=max(1,(int)($_GET['page']??1));$perPage=12;$allowed=['education','technology','travel','food','fashion','sport','other'];if(!in_array($category,$allowed,true))$category='';
$conditions=[];$params=[];$types='';if($search!==''){$conditions[]='(b.title LIKE ? OR b.description LIKE ? OR u.username LIKE ?)';$term='%'.$search.'%';$params=[$term,$term,$term];$types='sss';}if($category!==''){$conditions[]='b.category=?';$params[]=$category;$types.='s';}$where=$conditions?' WHERE '.implode(' AND ',$conditions):'';
$stmt=$con->prepare('SELECT COUNT(*) total FROM blogs b LEFT JOIN users u ON u.user_id=b.user_id'.$where);if($params)$stmt->bind_param($types,...$params);$stmt->execute();$total=(int)$stmt->get_result()->fetch_assoc()['total'];$stmt->close();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$sql='SELECT b.blog_id,b.title,b.created_at,b.description,b.category,b.image,b.likes,b.user_id,u.username'.$where.' ORDER BY b.created_at DESC LIMIT ? OFFSET ?';$feed=$params;$feed[]=$perPage;$feed[]=$offset;$stmt=$con->prepare($sql);$feedTypes=$types.'ii';$stmt->bind_param($feedTypes,...$feed);$stmt->execute();$posts=$stmt->get_result();$query=$_GET;unset($query['page']);$stmt->close();$con->close();
function blog_page_url(int $page,array $query):string{$query['page']=$page;return 'blog.php?'.http_build_query($query);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Discover public stories and writers on Weblogr."><meta name="robots" content="index,follow"><link rel="canonical" href="<?=e(public_url('blog.php'))?>"><link rel="icon" href="assets/weblogr-mark.svg" type="image/svg+xml"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.2/css/all.min.css"><link rel="stylesheet" href="assets/public.css"><title>Discover stories | Weblogr</title></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><nav class="nav" aria-label="Primary"><a class="brand" href="index.html"><span class="brand-mark">W</span> Weblogr</a><button class="mobile-menu" aria-label="Open navigation" aria-expanded="false"><i class="fas fa-bars"></i></button><div class="nav-links"><a href="blog.php" aria-current="page">Discover</a><a href="about.html">About</a><a href="registration/login.php">Log in</a><a class="nav-cta" href="registration/signup.php">Start writing</a></div></nav></header><main id="main"><div class="container"><section class="page-hero"><p class="eyebrow">DISCOVER</p><h1>Stories for curious minds.</h1><p>Read public stories, find new writers and explore ideas from the Weblogr community.</p></section><form class="filters" method="get" action="blog.php"><input type="search" name="search" value="<?=e($search)?>" maxlength="100" placeholder="Search stories or writers" aria-label="Search stories or writers"><select name="category" aria-label="Filter by category"><option value="">All categories</option><?php foreach($allowed as $item): ?><option value="<?=e($item)?>" <?=$category===$item?'selected':''?>><?=e(ucfirst($item))?></option><?php endforeach; ?></select><button class="button button-primary" type="submit">Search</button><?php if($search!==''||$category!==''): ?><a class="button button-secondary" href="blog.php">Clear</a><?php endif; ?></form><?php if($posts->num_rows): ?><div class="story-grid" data-public-feed data-next-page="<?=$page<$pages?$page+1:0?>" data-per-page="<?=$perPage?>" data-search="<?=e($search)?>" data-category="<?=e($category)?>"><?php while($post=$posts->fetch_assoc()): ?><article class="story-card"><a href="<?=e(article_url((int)$post['blog_id'],(string)$post['title']))?>" aria-label="Read <?=e((string)$post['title'])?>"><?php if(!empty($post['image'])): ?><img class="story-image" src="images/<?=rawurlencode((string)$post['image'])?>" alt="" loading="lazy"><?php else: ?><div class="story-image" aria-hidden="true"></div><?php endif; ?></a><div class="story-card-body"><span class="category"><?=e(strtoupper((string)$post['category']))?></span><h2><a href="<?=e(article_url((int)$post['blog_id'],(string)$post['title']))?>"><?=e((string)$post['title'])?></a></h2><p><?=e(excerpt((string)($post['description']??'')))?></p><div class="story-meta"><span><?php if($post['user_id']): ?><a href="<?=e(author_url((int)$post['user_id'],(string)$post['username']))?>">@<?=e((string)$post['username'])?></a><?php else: ?>Weblogr writer<?php endif; ?></span><span><?=e(date('d M Y',strtotime((string)$post['created_at'])))?></span></div></div></article><?php endwhile; ?></div><?php if($pages>1): ?><nav class="filters" aria-label="Pagination" data-server-pagination><?php if($page>1): ?><a class="button button-secondary" href="<?=e(blog_page_url($page-1,$query))?>">← Previous</a><?php endif; ?><span class="button button-secondary" aria-current="page">Page <?=$page?> of <?=$pages?></span><?php if($page<$pages): ?><a class="button button-primary" href="<?=e(blog_page_url($page+1,$query))?>">Next →</a><?php endif; ?></nav><div data-feed-sentinel class="feed-sentinel"></div><noscript><p>JavaScript is disabled. Use the pagination controls above to load more stories.</p></noscript><?php endif; ?><?php else: ?><div class="empty-state"><h2>No stories found</h2><p><?=($search!==''||$category!=='')?'Try a different search or category.':'The community has not published a story yet. Check back after writers start publishing.'?></p><?php if($search!==''||$category!==''): ?><a class="button button-secondary" href="blog.php">Reset filters</a><?php else: ?><a class="button button-primary" href="registration/signup.php">Become a writer</a><?php endif; ?></div><?php endif; ?></div></main><footer class="site-footer"><div class="container footer-inner"><span>© 2026 Weblogr · Built by Muhammad Talha</span><div class="footer-links"><a href="blog.php">Discover</a><a href="about.html">About</a><a href="privacy.html">Privacy</a><a href="terms.html">Terms</a></div></div></footer><script>const m=document.querySelector('.mobile-menu'),n=document.querySelector('.nav-links');m?.addEventListener('click',()=>{const o=m.getAttribute('aria-expanded')==='true';m.setAttribute('aria-expanded',String(!o));n.classList.toggle('open');});</script><script src="assets/public-feed.js" defer></script></body></html>
